-- IP1 Stages B and C (implementation plan IP1, 2026-09-27): cross-entity aggregation rules in the AI catalog, and
-- the data_need_spec/v2 tool contracts in Tool_Catalog.
--
-- Stage C: a relationship whose many side must be aggregated before a row join (Feature 02 -> Feature 03) is executable
-- only through saniti.preaggregate, which aggregates a column across entities of a finer grain (brokers and investor
-- types into a ticker-date-board row, boards into a ticker-date row) with the catalog rule of that column. The rule is
-- a new column, AI_column_catalog.cross_entity_aggregation, separate from resample_aggregation (which aggregates over
-- time). NULL means no rule: the column is never aggregated automatically. Only additive measures get SUM:
--   Feature_02_Broker_Rolling  daily buy/sell/net values and lots, and the 5/20/60-date net value and lot sums (12);
--   IDX_Broker_Summary         Buy/Sell/Net Value and Buy/Sell/Net Lots (6);
--   Feature_03_Stock_Broker_Daily  total buy/sell value and the investor-type and classification net values (8),
--                              aggregated across boards.
-- Left without a rule on purpose: ratios, z-scores, percentiles, day counts, broker counts, averages (Avg Buy/Sell),
-- concentration (HHI, top-3 shares), largest-day and top-broker values, positive-flow totals (a sum of positive parts is
-- not the positive part of a sum), and values repeated from a coarser grain (stock_trading_days_*).
--
-- Stage B: submit_data_need_spec v3 and check_data_feasibility v2 register the data_need_spec/v2 input (relationships
-- name every key pair: left_columns / right_columns), served by market-ai-orc when AI_ENABLE_COMPOSITE_KEYS is on and
-- the sandbox reports data_need_spec/v2. Inactive like the other DataNeed rows; the input schemas are generated from
-- the tool definitions. The limits and other columns are copied from the previous version.
--
-- Rollback (forward-only: write a new migration): set the 26 rules to NULL (saniti.preaggregate then refuses every
-- column) and delete the two Tool_Catalog rows; dropping the column needs Governor and sandbox versions that do not
-- read it (both check for it before reading).
BEGIN;

SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '2min';

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public'
               AND table_name = 'AI_column_catalog' AND column_name = 'cross_entity_aggregation') THEN
        RAISE EXCEPTION 'AI_column_catalog.cross_entity_aggregation already exists';
    END IF;
    IF (SELECT count(*) FROM public."AI_column_catalog" WHERE (table_name, column_name) IN (
        ('Feature_02_Broker_Rolling', 'buy_value_1d'),
        ('Feature_02_Broker_Rolling', 'sell_value_1d'),
        ('Feature_02_Broker_Rolling', 'net_value_1d'),
        ('Feature_02_Broker_Rolling', 'buy_lots_1d'),
        ('Feature_02_Broker_Rolling', 'sell_lots_1d'),
        ('Feature_02_Broker_Rolling', 'net_lots_1d'),
        ('Feature_02_Broker_Rolling', 'net_value_5d'),
        ('Feature_02_Broker_Rolling', 'net_value_20d'),
        ('Feature_02_Broker_Rolling', 'net_value_60d'),
        ('Feature_02_Broker_Rolling', 'net_lots_5d'),
        ('Feature_02_Broker_Rolling', 'net_lots_20d'),
        ('Feature_02_Broker_Rolling', 'net_lots_60d'),
        ('IDX_Broker_Summary', 'Buy Value'),
        ('IDX_Broker_Summary', 'Sell Value'),
        ('IDX_Broker_Summary', 'Net Value'),
        ('IDX_Broker_Summary', 'Buy Lots'),
        ('IDX_Broker_Summary', 'Sell Lots'),
        ('IDX_Broker_Summary', 'Net Lots'),
        ('Feature_03_Stock_Broker_Daily', 'total_buy_value'),
        ('Feature_03_Stock_Broker_Daily', 'total_sell_value'),
        ('Feature_03_Stock_Broker_Daily', 'foreign_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'domestic_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'institutional_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'retail_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'mixed_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'niche_net_value'))) <> 26 THEN
        RAISE EXCEPTION 'The 26 additive columns are not all in AI_column_catalog';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'submit_data_need_spec' AND version = 'v2')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'check_data_feasibility' AND version = 'v1')
       OR EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name, version) IN
                  (('submit_data_need_spec', 'v3'), ('check_data_feasibility', 'v2'))) THEN
        RAISE EXCEPTION 'Unexpected Tool_Catalog versions for the DataNeed tools';
    END IF;
END
$preflight$;

ALTER TABLE public."AI_column_catalog"
    ADD COLUMN cross_entity_aggregation text,
    ADD CONSTRAINT "AI_column_catalog_cross_entity_aggregation_check" CHECK (
        cross_entity_aggregation IS NULL OR cross_entity_aggregation IN ('SUM', 'MIN', 'MAX')
    );

COMMENT ON COLUMN public."AI_column_catalog".cross_entity_aggregation IS
    'Rule for aggregating this column across entities of a finer grain (for example brokers into a ticker-date-board row) before a relationship join (saniti.preaggregate); NULL = not additive, never aggregated automatically.';

UPDATE public."AI_column_catalog" SET cross_entity_aggregation = 'SUM'
WHERE (table_name, column_name) IN (
        ('Feature_02_Broker_Rolling', 'buy_value_1d'),
        ('Feature_02_Broker_Rolling', 'sell_value_1d'),
        ('Feature_02_Broker_Rolling', 'net_value_1d'),
        ('Feature_02_Broker_Rolling', 'buy_lots_1d'),
        ('Feature_02_Broker_Rolling', 'sell_lots_1d'),
        ('Feature_02_Broker_Rolling', 'net_lots_1d'),
        ('Feature_02_Broker_Rolling', 'net_value_5d'),
        ('Feature_02_Broker_Rolling', 'net_value_20d'),
        ('Feature_02_Broker_Rolling', 'net_value_60d'),
        ('Feature_02_Broker_Rolling', 'net_lots_5d'),
        ('Feature_02_Broker_Rolling', 'net_lots_20d'),
        ('Feature_02_Broker_Rolling', 'net_lots_60d'),
        ('IDX_Broker_Summary', 'Buy Value'),
        ('IDX_Broker_Summary', 'Sell Value'),
        ('IDX_Broker_Summary', 'Net Value'),
        ('IDX_Broker_Summary', 'Buy Lots'),
        ('IDX_Broker_Summary', 'Sell Lots'),
        ('IDX_Broker_Summary', 'Net Lots'),
        ('Feature_03_Stock_Broker_Daily', 'total_buy_value'),
        ('Feature_03_Stock_Broker_Daily', 'total_sell_value'),
        ('Feature_03_Stock_Broker_Daily', 'foreign_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'domestic_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'institutional_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'retail_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'mixed_net_value'),
        ('Feature_03_Stock_Broker_Daily', 'niche_net_value'));

INSERT INTO public."Column_Catalog" (
    table_schema, table_name, column_name, ordinal_position, data_type,
    is_nullable, default_expression, is_primary_key, definition,
    source_column_or_expression, unit, null_rule, source_code_paths,
    documentation_status
)
SELECT columns.table_schema, columns.table_name, columns.column_name, columns.ordinal_position,
       columns.data_type, true, NULL, false,
       'Rule for aggregating the column across entities of a finer grain before a relationship join (SUM, MIN, MAX); '
       'NULL means the column is not additive and is never aggregated automatically. Used by saniti.preaggregate '
       '(market-python-sandbox), read through the Governor catalog contract.',
       'Curated by migration 20260927_005', NULL, 'NULL when no cross-entity rule is established.',
       ARRAY['database/migrations/20260927_005_cross_entity_aggregation_and_v2_contracts.sql',
             'apps/market-sql-governor/app/catalog_contract.py',
             'apps/market-python-sandbox/runtime/saniti_session.py'],
       'PARTIAL'
FROM information_schema.columns AS columns
WHERE columns.table_schema = 'public' AND columns.table_name = 'AI_column_catalog'
  AND columns.column_name = 'cross_entity_aggregation';

UPDATE public."Table_Catalog"
SET source_code_paths = array_append(source_code_paths,
                                     'database/migrations/20260927_005_cross_entity_aggregation_and_v2_contracts.sql')
WHERE table_schema = 'public' AND table_name = 'AI_column_catalog'
  AND NOT ('database/migrations/20260927_005_cross_entity_aggregation_and_v2_contracts.sql' = ANY(source_code_paths));

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
