     '{"feature_flag":"AI_ENABLE_COMPOSITE_KEYS","registry_state":"data_need_spec/v2 input. Registered in market-ai-orc only with AI_ENABLE_PLAN_FEASIBILITY and AI_ENABLE_COMPOSITE_KEYS; v1 input otherwise.","runtime_commit":"9262fd8","spec_version":"data_need_spec/v2"}'::jsonb)
) AS next(name, from_version, version, input_schema, limits)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."AI_column_catalog" WHERE cross_entity_aggregation = 'SUM') <> 26
       OR EXISTS (SELECT 1 FROM public."AI_column_catalog"
                  WHERE cross_entity_aggregation IS NOT NULL AND data_type NOT IN ('numeric', 'bigint', 'integer',
                                                                                  'smallint', 'double precision')) THEN
        RAISE EXCEPTION 'The cross-entity rules are not as expected';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Column_Catalog" WHERE table_name = 'AI_column_catalog'
                   AND column_name = 'cross_entity_aggregation') THEN
        RAISE EXCEPTION 'Column_Catalog lacks cross_entity_aggregation';
    END IF;
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active
        AND ((tool_name = 'submit_data_need_spec' AND version = 'v3')
             OR (tool_name = 'check_data_feasibility' AND version = 'v2'))
        AND input_schema->'properties'->'spec_version'->'enum' = '["data_need_spec/v2"]'::jsonb) <> 2 THEN
        RAISE EXCEPTION 'The data_need_spec/v2 tool contracts were not registered';
    END IF;
END
$verify$;

COMMIT;
